"use client";

import React, { useState, Suspense } from "react";
import { Search, MapPin, ExternalLink, X, SlidersHorizontal, Maximize2, Map as MapIcon, CheckCircle2, Navigation } from "lucide-react";
import Link from "next/link";
import { useSearchParams, useRouter } from "next/navigation";
import { useGetSuppliersQuery } from "@/store/api/supplierApi";
import DynamicMap from "@/components/home/DynamicMap";

const initialTags = ['Verified Suppliers', 'Premium Listings'];

function SearchContent() {
  const searchParams = useSearchParams();
  const router = useRouter();

  // Initialize query from URL parameters
  const urlQuery = searchParams.get("q") || "";
  const urlTypesParam = searchParams.get("type");
  const urlTypes = urlTypesParam ? urlTypesParam.split(',') : ['Manufacturer', 'Distributor', 'Service Provider'];
  const urlLocation = searchParams.get("loc") || "";

  const [query, setQuery] = useState(urlQuery);
  const [activeTags, setActiveTags] = useState(initialTags);
  const [isMapExpanded, setIsMapExpanded] = useState(false);

  // State for filters
  const [selectedTypes, setSelectedTypes] = useState<string[]>(urlTypes);
  const [locationSearch, setLocationSearch] = useState(urlLocation);

  // Sync local state when URL changes (e.g. browser back/forward)
  React.useEffect(() => {
    setQuery(urlQuery);
    setSelectedTypes(urlTypesParam ? urlTypesParam.split(',') : ['Manufacturer', 'Distributor', 'Service Provider']);
    setLocationSearch(urlLocation);
  }, [urlQuery, urlTypesParam, urlLocation]);

  // Debounce user input and push to URL automatically
  React.useEffect(() => {
    const timeoutId = setTimeout(() => {
      const params = new URLSearchParams();
      if (query) params.set("q", query);
      if (selectedTypes.length > 0) params.set("type", selectedTypes.join(','));
      if (locationSearch) params.set("loc", locationSearch);
      
      const currentQuery = searchParams.toString();
      const newQuery = params.toString();
      
      if (currentQuery !== newQuery) {
        router.push(`/search?${newQuery}`);
      }
    }, 400); // 400ms debounce
    return () => clearTimeout(timeoutId);
  }, [query, selectedTypes, locationSearch, router, searchParams]);

  // Build query string for API
  const queryParts = [];
  if (urlQuery) queryParts.push(`keyword=${encodeURIComponent(urlQuery)}`);
  if (urlTypes && urlTypes.length > 0) queryParts.push(`supplierType=${encodeURIComponent(urlTypes.join(','))}`);
  if (urlLocation) queryParts.push(`location=${encodeURIComponent(urlLocation)}`);
  
  const queryString = queryParts.join('&');

  // Fetch real suppliers from backend
  const { data, isLoading } = useGetSuppliersQuery(queryString);
  const suppliers = data?.data || [];

  // Temporarily disable counts as we are now fully dynamically fetching from backend. 
  // For accurate counts, a dedicated aggregation endpoint would be needed.
  const counts = {
    Manufacturer: suppliers.filter((s: any) => (s.supplierType || 'Manufacturer') === 'Manufacturer').length,
    Distributor: suppliers.filter((s: any) => s.supplierType === 'Distributor').length,
    ServiceProvider: suppliers.filter((s: any) => s.supplierType === 'Service Provider').length,
  };

  const handleTypeToggle = (type: string) => {
    setSelectedTypes(prev =>
      prev.includes(type) ? prev.filter(t => t !== type) : [...prev, type]
    );
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
  };

  const removeTag = (tagToRemove: string) => {
    setActiveTags(activeTags.filter(tag => tag !== tagToRemove));
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC]">
      <div className="mx-auto max-w-[1280px] px-4 py-6 sm:px-6 lg:px-8">

        {/* Breadcrumbs */}
        <div className="flex items-center gap-2 text-sm text-slate-500 mb-6">
          <Link href="/" className="hover:text-slate-900">Home</Link>
          <span>/</span>
          <span className="hover:text-slate-900 cursor-pointer">Search</span>
          <span>/</span>
          <span className="font-semibold text-slate-900 capitalize">{urlQuery}</span>
        </div>

        {/* Page Title */}
        <h1 className="text-3xl font-bold text-[#0F172A] mb-2">Search Results for &quot;{urlQuery}&quot;</h1>
        <p className="text-slate-500 mb-8">Find suppliers, manufacturers, and industrial service providers near your location.</p>

        {/* Main Search Input */}
        <form onSubmit={handleSearch} className="flex bg-white rounded-lg border border-slate-300 overflow-hidden shadow-sm mb-4 max-w-3xl">
          <div className="flex items-center pl-4 pr-2 text-slate-400">
            <Search size={20} />
          </div>
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="flex-1 py-3 focus:outline-none text-slate-700 font-medium"
          />
          <button type="submit" className="bg-[#DFB63E] hover:bg-[#cba433] transition-colors text-slate-900 font-bold px-8 py-3">
            Search
          </button>
        </form>

        {/* Filter Tags */}
        <div className="flex items-center gap-3 mb-8">
          <button type="button" className="p-2 border border-slate-300 rounded-md bg-white text-slate-600 hover:bg-slate-50">
            <SlidersHorizontal size={18} />
          </button>
          <div className="flex flex-wrap gap-2">
            {activeTags.map(tag => (
              <span key={tag} className="flex items-center gap-1.5 bg-[#E2E8F0] text-[#334155] px-3 py-1.5 rounded-full text-sm font-medium">
                {tag} <X size={14} className="cursor-pointer hover:text-slate-800" onClick={() => removeTag(tag)} />
              </span>
            ))}
          </div>
        </div>

        {/* Main Grid Content */}
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">

          {/* Left Column: Filters */}
          <div className="lg:col-span-1">
            <div className="bg-white border border-slate-200 rounded-lg p-5">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-lg font-bold text-slate-900">Filters</h2>
                <button type="button" className="text-sm font-semibold text-[#2563EB] hover:underline" onClick={() => setActiveTags([])}>Clear All</button>
              </div>

              {/* Supplier Category */}
              <div className="mb-6">
                <h3 className="text-sm font-bold text-slate-900 mb-3">Supplier Category</h3>
                <div className="space-y-3">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={selectedTypes.includes('Manufacturer')}
                      onChange={() => handleTypeToggle('Manufacturer')}
                      className="w-4 h-4 text-[#0F172A] rounded border-slate-300 focus:ring-[#0F172A]"
                    />
                    <span className="text-sm text-slate-600">Manufacturer ({counts.Manufacturer})</span>
                  </label>
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={selectedTypes.includes('Distributor')}
                      onChange={() => handleTypeToggle('Distributor')}
                      className="w-4 h-4 text-[#0F172A] rounded border-slate-300 focus:ring-[#0F172A]"
                    />
                    <span className="text-sm text-slate-600">Distributor ({counts.Distributor})</span>
                  </label>
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={selectedTypes.includes('Service Provider')}
                      onChange={() => handleTypeToggle('Service Provider')}
                      className="w-4 h-4 text-[#0F172A] rounded border-slate-300 focus:ring-[#0F172A]"
                    />
                    <span className="text-sm text-slate-600">Service Provider ({counts.ServiceProvider})</span>
                  </label>
                </div>
              </div>

              <hr className="border-slate-200 my-4" />

              {/* Location */}
              <div className="mb-6">
                <h3 className="text-sm font-bold text-slate-900 mb-3">Location</h3>

                <div className="space-y-4">
                  <div>
                    <label className="block text-xs text-slate-500 mb-1">Search Location</label>
                    <input
                      type="text"
                      value={locationSearch}
                      onChange={(e) => setLocationSearch(e.target.value)}
                      placeholder="e.g. New York, NY"
                      className="w-full text-black border border-slate-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:border-[#DFB63E] focus:ring-1 focus:ring-[#DFB63E]"
                    />
                  </div>
                </div>
              </div>

              {/* Apply Filters button removed since filtering is now real-time dynamic */}
            </div>
          </div>

          {/* Middle Column: Results */}
          <div className="lg:col-span-2">
            <div className="flex items-center justify-between mb-4">
              <span className="text-sm font-bold text-slate-900">{isLoading ? "Searching..." : `${suppliers.length} suppliers found`}</span>
              <div className="flex items-center gap-2 text-sm">
                <span className="text-slate-500">Sort by:</span>
                <select className="border border-slate-300 rounded-md px-2 py-1 text-slate-900 font-medium focus:outline-none bg-white">
                  <option>Recommended</option>
                  <option>Distance</option>
                  <option>Rating</option>
                </select>
              </div>
            </div>

            <div className="space-y-4">
              {suppliers.map((supplier: any) => (
                <div key={supplier._id} className="bg-white border border-slate-200 rounded-lg p-5">
                  <div className="flex justify-between items-start mb-2">
                    <div className="flex items-center gap-2">
                      <h3 className="text-xl font-bold text-slate-900">{supplier.companyName}</h3>
                      {supplier.isApproved && <CheckCircle2 size={18} className="text-[#10B981] fill-[#10B981]/10" />}
                    </div>
                    <div className="flex items-center gap-2">
                      {supplier.subscriptionPlan !== 'basic' && <span className="bg-[#EFF6FF] text-[#1D4ED8] text-xs font-bold px-2 py-1 rounded capitalize">{supplier.subscriptionPlan}</span>}
                    </div>
                  </div>

                  <div className="flex items-center gap-1.5 text-sm text-slate-500 mb-4">
                    <MapPin size={14} />
                    <span className="truncate">{supplier.location?.formattedAddress || supplier.address || 'Location not specified'} {supplier.isVerified && '• Verified'}</span>
                  </div>

                  <div className="mb-4 space-y-1">
                    <p className="text-sm"><span className="font-semibold text-slate-700">Description:</span> <span className="text-slate-900 font-medium">{supplier.description?.substring(0, 100)}...</span></p>
                  </div>

                  <div className="flex flex-wrap gap-2 mb-6">
                    {supplier.categories?.map((cat: any) => (
                      <span key={cat._id} className="bg-[#E2E8F0] text-slate-700 text-xs font-semibold px-2.5 py-1 rounded-full">
                        {cat.name}
                      </span>
                    ))}
                  </div>

                  <div className="flex items-center justify-end gap-3 pt-4 border-t border-slate-100">
                    <Link href={`/suppliers/${supplier._id}`} className="flex items-center gap-2 px-4 py-2 border border-slate-300 text-slate-700 font-bold text-sm rounded hover:bg-slate-50 transition-colors">
                      <ExternalLink size={14} /> View Profile
                    </Link>
                    <Link href={`/suppliers/${supplier._id}?action=rfq`} className="flex items-center gap-2 px-4 py-2 bg-[#DFB63E] hover:bg-[#cba433] text-slate-900 font-bold text-sm rounded transition-colors">
                      <Navigation size={14} className="rotate-45" /> Send RFQ
                    </Link>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Right Column: Map */}
          <div className={isMapExpanded ? "fixed inset-0 z-50 p-4 sm:p-8 bg-black/50 backdrop-blur-sm flex items-center justify-center" : "lg:col-span-1"}>
            <div className={`bg-white border border-slate-200 overflow-hidden flex flex-col transition-all duration-300 ${isMapExpanded ? "w-full h-full max-w-6xl max-h-[90vh] rounded-2xl shadow-2xl" : "h-[600px] sticky top-24 rounded-lg"}`}>
              <div className="flex items-center justify-between p-3 border-b border-slate-200 bg-white">
                <div className="flex items-center gap-2 text-slate-900 font-bold text-sm">
                  <MapIcon size={16} />
                  Nearby Suppliers Map
                </div>
                <button
                  onClick={() => setIsMapExpanded(!isMapExpanded)}
                  className="text-slate-400 hover:text-slate-600 p-1 rounded-md hover:bg-slate-100 transition-colors"
                  title={isMapExpanded ? "Minimize Map" : "Maximize Map"}
                >
                  {isMapExpanded ? <X size={16} /> : <Maximize2 size={16} />}
                </button>
              </div>
              <div className="flex-1 bg-slate-100 relative overflow-hidden">
                <DynamicMap suppliers={suppliers} />
              </div>
            </div>
          </div>

        </div>
      </div>
    </div>
  );
}

export default function SearchScreen() {
  return (
    <Suspense fallback={<div className="min-h-screen bg-[#F8FAFC] flex items-center justify-center">Loading...</div>}>
      <SearchContent />
    </Suspense>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { useDispatch, useSelector } from "react-redux";
import { registerUser, verifyEmailUser, clearError } from "@/store/slices/authSlice";
import { AppDispatch, RootState } from "@/store/store";
import toast from "react-hot-toast";
import logoImg from "../../../public/assets/logo.png";
import authBg from "../../../public/assets/auth-bg.png";
import {
  User,
  Mail,
  Lock,
  Eye,
  EyeOff,
  ArrowRight,
  BookmarkCheck,
  FileText,
  MessageSquare,
  LayoutDashboard,
  Bookmark,
} from "lucide-react";

export default function SignUpPage() {
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [formData, setFormData] = useState({
    fullName: "",
    workEmail: "",
    password: "",
    confirmPassword: "",
  });

  const [showOtpModal, setShowOtpModal] = useState(false);
  const [otpCode, setOtpCode] = useState("");
  const [error, setError] = useState("");
  const router = useRouter();
  const dispatch = useDispatch<AppDispatch>();
  const { isLoading, error: reduxError, token } = useSelector((state: RootState) => state.auth);

  React.useEffect(() => {
    dispatch(clearError());
  }, [dispatch]);

  React.useEffect(() => {
    if (token) {
      router.push("/dashboard");
    }
  }, [token, router]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError("");
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.password !== formData.confirmPassword) {
      setError("Passwords do not match.");
      return;
    }
    if (!formData.fullName || !formData.workEmail || !formData.password) {
      setError("Please fill in all fields.");
      return;
    }
    dispatch(registerUser({ 
      name: formData.fullName, 
      email: formData.workEmail, 
      password: formData.password,
      role: "buyer" // Automatically set to buyer based on UI design
    }))
      .unwrap()
      .then(() => {
        toast.success("Registration successful! Please check your email for the verification code.");
        setShowOtpModal(true);
      })
      .catch((err) => {
        toast.error(err || "Registration failed");
      });
  };

  const handleContinueAsGuest = () => {
    localStorage.setItem("guestMode", "true");
    localStorage.removeItem("token");
    router.push("/dashboard");
  };

  const handleVerifyEmail = (e: React.FormEvent) => {
    e.preventDefault();
    if (!otpCode) {
      toast.error("Please enter the verification code");
      return;
    }
    dispatch(verifyEmailUser({ email: formData.workEmail, verifyCode: otpCode }))
      .unwrap()
      .then(() => {
        toast.success("Email verified successfully! Redirecting to login...", {
          duration: 2000,
        });
        setTimeout(() => {
          router.push("/login");
        }, 2000);
      })
      .catch((err) => {
        toast.error(err || "Verification failed");
      });
  };

  return (
    <div className="flex min-h-screen">
      {/* ───── Left Panel: Sign Up Form ───── */}
      <div className="w-full lg:w-1/2 flex flex-col justify-center items-center px-8 sm:px-12 md:px-16 lg:px-20 py-10 bg-white relative">
        {/* Form Content */}
        <div className="max-w-[340px] w-full">
          {/* Logo */}
          <div className="mb-10">
            <Link href="/" className="flex items-center gap-2.5">
              <Image
                src={logoImg}
                alt="Wulfara Logo"
                width={28}
                height={28}
                className="h-7 w-7 object-contain"
                priority
              />
              <span className="text-lg font-black tracking-wider text-[#1b2b3a] uppercase">
                WULFARA
              </span>
            </Link>
          </div>

          <h1 className="text-3xl sm:text-4xl font-bold text-[#1b2b3a] leading-tight mb-2">
            Create your
            <br />
            account
          </h1>
          <p className="text-sm text-gray-500 mb-8">
            Access your RFQs, saved suppliers,
            <br />
            and messages.
          </p>

          <form onSubmit={handleSubmit} className="space-y-5">
            {(error || reduxError) && (
              <div className="p-3 rounded-md bg-red-50 border border-red-200 text-red-600 text-sm font-medium">
                {error || reduxError}
              </div>
            )}
            {/* Full Name */}
            <div>
              <label
                htmlFor="fullName"
                className="block text-sm font-semibold text-[#1b2b3a] mb-2"
              >
                Full Name
              </label>
              <div className="relative">
                <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400">
                  <User size={18} />
                </span>
                <input
                  id="fullName"
                  name="fullName"
                  type="text"
                  placeholder="John Doe"
                  value={formData.fullName}
                  onChange={handleChange}
                  className="w-full rounded-lg border border-gray-200 bg-gray-50/60 py-3 pl-11 pr-4 text-sm text-gray-700 placeholder-gray-400 outline-none transition-all focus:border-[#dca12f] focus:ring-2 focus:ring-[#dca12f]/20"
                />
              </div>
            </div>

            {/* Work Email */}
            <div>
              <label
                htmlFor="workEmail"
                className="block text-sm font-semibold text-[#1b2b3a] mb-2"
              >
                Work Email
              </label>
              <div className="relative">
                <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400">
                  <Mail size={18} />
                </span>
                <input
                  id="workEmail"
                  name="workEmail"
                  type="email"
                  placeholder="john@company.com"
                  value={formData.workEmail}
                  onChange={handleChange}
                  className="w-full rounded-lg border border-gray-200 bg-gray-50/60 py-3 pl-11 pr-4 text-sm text-gray-700 placeholder-gray-400 outline-none transition-all focus:border-[#dca12f] focus:ring-2 focus:ring-[#dca12f]/20"
                />
              </div>
            </div>

            {/* Password */}
            <div>
              <label
                htmlFor="password"
                className="block text-sm font-semibold text-[#1b2b3a] mb-2"
              >
                Password
              </label>
              <div className="relative">
                <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400">
                  <Lock size={18} />
                </span>
                <input
                  id="password"
                  name="password"
                  type={showPassword ? "text" : "password"}
                  placeholder="••••••••"
                  value={formData.password}
                  onChange={handleChange}
                  className="w-full rounded-lg border border-gray-200 bg-gray-50/60 py-3 pl-11 pr-11 text-sm text-gray-700 placeholder-gray-400 outline-none transition-all focus:border-[#dca12f] focus:ring-2 focus:ring-[#dca12f]/20"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3.5 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 transition-colors"
                  aria-label={showPassword ? "Hide password" : "Show password"}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {/* Confirm Password */}
            <div>
              <label
                htmlFor="confirmPassword"
                className="block text-sm font-semibold text-[#1b2b3a] mb-2"
              >
                Confirm Password
              </label>
              <div className="relative">
                <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400">
                  <Lock size={18} />
                </span>
                <input
                  id="confirmPassword"
                  name="confirmPassword"
                  type={showConfirmPassword ? "text" : "password"}
                  placeholder="••••••••"
                  value={formData.confirmPassword}
                  onChange={handleChange}
                  className="w-full rounded-lg border border-gray-200 bg-gray-50/60 py-3 pl-11 pr-11 text-sm text-gray-700 placeholder-gray-400 outline-none transition-all focus:border-[#dca12f] focus:ring-2 focus:ring-[#dca12f]/20"
                />
                <button
                  type="button"
                  onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                  className="absolute right-3.5 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 transition-colors"
                  aria-label={
                    showConfirmPassword ? "Hide password" : "Show password"
                  }
                >
                  {showConfirmPassword ? (
                    <EyeOff size={18} />
                  ) : (
                    <Eye size={18} />
                  )}
                </button>
              </div>
            </div>

            {/* Submit Button */}
            <button
              type="submit"
              disabled={isLoading}
              id="create-buyer-account-btn"
              className="w-full flex items-center justify-center gap-2 rounded-lg bg-[#dca12f] hover:bg-[#c99126] py-3.5 text-sm font-bold text-[#1b2b3a] transition-all duration-200 shadow-md hover:shadow-lg cursor-pointer active:scale-[0.98] disabled:opacity-70 disabled:cursor-not-allowed"
            >
              {isLoading ? "Creating Account..." : "Create Buyer Account"}
              {!isLoading && <ArrowRight size={16} strokeWidth={2.5} />}
            </button>

            {/* Continue as Guest */}
            <button
              type="button"
              id="continue-as-guest-btn"
              onClick={handleContinueAsGuest}
              className="w-full rounded-lg border border-gray-200 bg-white py-3.5 text-sm font-semibold text-[#1b2b3a] transition-all duration-200 hover:bg-gray-50 hover:border-gray-300 cursor-pointer active:scale-[0.98]"
            >
              Continue as Guest
            </button>
          </form>

          {/* Login Link */}
          <p className="text-sm text-gray-500 mt-8 text-center">
            Already have an account?{" "}
            <Link
              href="/login"
              className="text-[#dca12f] font-semibold hover:text-[#c99126] transition-colors"
            >
              Login here
            </Link>
          </p>
        </div>
      </div>

      {/* ───── Right Panel: Buyer Workspace Showcase ───── */}
      <div className="hidden lg:flex lg:w-1/2 bg-[#0f1b2d] relative overflow-hidden flex-col justify-center px-12 xl:px-20">
        {/* Background image */}
        <Image
          src={authBg}
          alt=""
          fill
          sizes="50vw"
          className="object-cover opacity-20"
          priority
        />
        {/* Dark overlay */}
        <div className="absolute inset-0 bg-[#0f1b2d]/70" />
        {/* Background gradient accents */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-[#dca12f]/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/3" />
        <div className="absolute bottom-0 left-0 w-80 h-80 bg-[#1e3a5f]/30 rounded-full blur-3xl translate-y-1/3 -translate-x-1/4" />

        <div className="relative z-10 max-w-[520px]">
          {/* Heading */}
          <h2 className="text-4xl xl:text-5xl font-black text-white leading-tight mb-4">
            Your buyer
            <br />
            workspace
          </h2>
          <p className="text-[15px] text-slate-400 leading-relaxed mb-10 max-w-md">
            A centralized, high-efficiency hub to manage your industrial
            procurement lifecycle securely.
          </p>

          {/* Feature Cards */}
          <div className="grid grid-cols-2 gap-4 mb-4">
            {/* Save Suppliers */}
            <div className="bg-[#162236]/80 backdrop-blur-md border border-slate-700/50 rounded-xl p-5 hover:border-slate-600/60 transition-colors group">
              <div className="w-10 h-10 rounded-lg bg-[#dca12f]/15 flex items-center justify-center mb-3">
                <Bookmark size={20} className="text-[#dca12f]" />
              </div>
              <h3 className="text-sm font-semibold text-white mb-1">
                Save Suppliers
              </h3>
              <p className="text-xs text-slate-400 leading-relaxed">
                Curate your trusted network.
              </p>
            </div>

            {/* Track RFQs */}
            <div className="bg-[#162236] border border-slate-700/50 rounded-xl p-5 hover:border-slate-600/60 transition-colors group">
              <div className="w-10 h-10 rounded-lg bg-[#dca12f]/15 flex items-center justify-center mb-3">
                <FileText size={20} className="text-[#dca12f]" />
              </div>
              <h3 className="text-sm font-semibold text-white mb-1">
                Track RFQs
              </h3>
              <p className="text-xs text-slate-400 leading-relaxed">
                Monitor active bids instantly.
              </p>
            </div>
          </div>

          {/* Message Suppliers - Full Width */}
          <div className="bg-[#162236] border border-slate-700/50 rounded-xl p-5 mb-8 hover:border-slate-600/60 transition-colors group flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 rounded-lg bg-[#dca12f]/15 flex items-center justify-center flex-shrink-0">
                <Mail size={20} className="text-[#dca12f]" />
              </div>
              <div>
                <h3 className="text-sm font-semibold text-white mb-0.5">
                  Message Suppliers
                </h3>
                <p className="text-xs text-slate-400">
                  Direct, secure communication channels.
                </p>
              </div>
            </div>
            <ArrowRight
              size={18}
              className="text-slate-500 group-hover:text-[#dca12f] transition-colors shrink-0"
            />
          </div>

          {/* Dashboard Overview Card */}
          <div className="bg-[#ffff] border-t-4 border-[#D4AF37] rounded-xl p-6">
            <div className="flex items-center justify-between mb-5">
              <div className="flex items-center gap-1">
                <LayoutDashboard size={14} className="text-[#000000]" />
                <h3 className="text-sm font-semibold text-[#000000]">
                  Dashboard Overview
                </h3>
              </div>
              <span className="text-xs font-medium text-[#44474D] bg-[#E5EEFF] px-3 py-1 rounded-[16px]">
                Live Data
              </span>
            </div>
            <div className="grid grid-cols-3 gap-4">
              <div className="text-center border-r border-slate-700/50 pr-4">
                <p className="text-3xl font-bold text-black mb-1">4</p>
                <p className="text-[10px] font-medium text-[#44474D] uppercase tracking-wider">
                  Active RFQs
                </p>
              </div>
              <div className="text-center border-r border-slate-700/50 pr-4">
                <p className="text-3xl font-bold text-black mb-1">8</p>
                <p className="text-[10px] font-medium text-[#44474D] uppercase tracking-wider">
                  Favorite Suppliers
                </p>
              </div>
              <div className="text-center">
                <p className="text-3xl font-bold text-black mb-1">2</p>
                <p className="text-[10px] font-medium text-[#44474D] uppercase tracking-wider">
                  Recent Messages
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* ───── OTP Verification Modal ───── */}
      {showOtpModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-8 text-center relative overflow-hidden">
            {/* Top accent line */}
            <div className="absolute top-0 left-0 right-0 h-1 bg-[#D4AF37]"></div>
            
            <div className="mx-auto w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mb-6">
              <Mail className="text-[#1b2b3a] w-8 h-8" />
            </div>
            
            <h2 className="text-2xl font-bold text-[#1b2b3a] mb-2">Check your email</h2>
            <p className="text-gray-500 mb-8">
              We&apos;ve sent a verification code to <br />
              <span className="font-semibold text-gray-800">{formData.workEmail}</span>
            </p>

            <form onSubmit={handleVerifyEmail}>
              <div className="mb-6">
                <input
                  type="text"
                  placeholder="Enter 6-digit code"
                  value={otpCode}
                  onChange={(e) => setOtpCode(e.target.value)}
                  className="w-full text-center text-black text-2xl tracking-[0.5em] font-mono py-4 border-2 border-gray-200 rounded-xl focus:border-[#dca12f] focus:ring-0 transition-colors outline-none"
                  maxLength={6}
                />
              </div>

              <button
                type="submit"
                disabled={isLoading || otpCode.length < 6}
                className="w-full bg-[#1b2b3a] hover:bg-[#14202b] text-white font-medium py-3.5 px-4 rounded-xl transition-all flex justify-center items-center gap-2 group disabled:opacity-70 disabled:cursor-not-allowed"
              >
                {isLoading ? (
                  <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                ) : (
                  <>
                    Verify Email
                    <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
                  </>
                )}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import React from "react";
import Link from "next/link";
import {
  MapPin,
  Clock,
  Phone,
  Mail,
  Building2,
  FileText,
  ArrowRight,
  CheckCircle2,
  Wrench,
  Box,
  Layers,
  ChevronLeft,
  Settings,
  ExternalLink,
  Heart,
  Star
} from "lucide-react";

import { useSelector } from "react-redux";
import toast from "react-hot-toast";
import { useGetFavoritesQuery, useAddFavoriteMutation, useRemoveFavoriteMutation } from "@/store/api/favoriteApi";

import { useGetSupplierByIdQuery } from "@/store/api/supplierApi";
import { useGetSupplierReviewsQuery } from "@/store/api/reviewApi";
import { useParams } from "next/navigation";
import DynamicMap from "@/components/home/DynamicMap";

export default function SupplierProfilePage() {
  const params = useParams();
  const id = params.id as string;
  const { data, isLoading } = useGetSupplierByIdQuery(id, { skip: !id });
  const supplier = data?.data;

  const user = useSelector((state: any) => state.auth.user);
  const { data: favoritesData } = useGetFavoritesQuery(undefined, { skip: !user });
  const [addFavorite] = useAddFavoriteMutation();
  const [removeFavorite] = useRemoveFavoriteMutation();
  const favorites = favoritesData?.data || [];
  
  const { data: reviewsData } = useGetSupplierReviewsQuery(id, { skip: !id });
  const reviews = reviewsData?.data || [];

  const handleFavoriteToggle = async () => {
    if (!user) {
      toast.error("Please login to save favorites");
      return;
    }
    const existingFav = favorites.find((f: any) => f.supplier?._id === id || f.supplier === id);
    try {
      if (existingFav) {
        await removeFavorite(existingFav._id).unwrap();
        toast.success("Removed from favorites");
      } else {
        await addFavorite({ supplierId: id }).unwrap();
        toast.success("Added to favorites");
      }
    } catch (err: any) {
      toast.error(err?.data?.message || "Failed to update favorites");
    }
  };

  if (isLoading) {
    return <div className="min-h-screen bg-[#F8FAFC] flex items-center justify-center">Loading...</div>;
  }

  if (!supplier) {
    return <div className="min-h-screen bg-[#F8FAFC] flex items-center justify-center">Supplier not found.</div>;
  }

  // Map real supplier data
  const displayLocation = supplier.contactInfo?.address || "Location not specified";
  const displayReplyTime = "Replies in 24 hours"; // Could be dynamically calculated if tracked
  const displayAbout = supplier.description || "No description provided.";

  // Dynamically map core products/services
  const displayServices = supplier.coreProducts && supplier.coreProducts.length > 0
    ? supplier.coreProducts.map((prod: string) => ({
      title: prod,
      desc: "Core product/service offered by the supplier.",
      icon: <Wrench size={16} />
    }))
    : [{ title: "Core Services", desc: "Industrial sourcing and supply.", icon: <Wrench size={16} /> }];

  const displayGallery = supplier.gallery && supplier.gallery.length > 0
    ? supplier.gallery.map((g: any) => g.url)
    : [];

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-20">
      <div className="max-w-[1280px] mx-auto px-4 sm:px-6 py-8">

        {/* Breadcrumb / Back Navigation */}
        <Link href="/suppliers" className="inline-flex items-center gap-1 text-sm font-medium text-slate-500 hover:text-slate-800 mb-6 transition-colors">
          <ChevronLeft size={16} /> Back to Search Results
        </Link>

        {/* Top Header Card */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 flex flex-col md:flex-row items-center justify-between gap-6 mb-6">
          <div className="flex flex-col sm:flex-row items-center sm:items-start gap-6 w-full md:w-auto text-center sm:text-left">
            {/* Logo */}
            <div className="w-24 h-24 rounded bg-linear-to-tr from-slate-800 to-[#1b2b3a] shrink-0 flex items-center justify-center relative overflow-hidden shadow-inner">
              {(supplier.logo && supplier.logo !== 'no-logo.jpg') ? (
                <img src={supplier.logo} alt="Logo" className="w-full h-full object-cover" />
              ) : (
                <div className="w-12 h-12 border-4 border-white/20 rounded-full flex items-center justify-center relative z-10">
                  <Building2 className="text-white/80" size={24} />
                </div>
              )}
              {supplier.isApproved && (
                <div className="absolute -bottom-1 -right-1 bg-emerald-500 text-white rounded-full p-0.5 border-2 border-white z-20">
                  <CheckCircle2 size={16} />
                </div>
              )}
            </div>

            <div className="flex flex-col justify-center h-full pt-1">
              <div className="flex flex-col sm:flex-row items-center gap-3 mb-3">
                <h1 className="text-3xl font-black text-[#1b2b3a] tracking-tight">{supplier.companyName}</h1>
                {supplier.subscriptionPlan !== 'basic' && (
                  <span className="px-3 py-1 bg-[#fff8e6] text-[#b8860b] text-[11px] font-bold rounded-full uppercase tracking-wider flex items-center gap-1 border border-[#f5e3b5]">
                    <span className="w-2 h-2 rounded-full bg-[#dca12f]"></span> {supplier.subscriptionPlan} Supplier
                  </span>
                )}
              </div>
              <div className="flex flex-wrap items-center justify-center sm:justify-start gap-4 text-sm text-slate-500 font-medium">
                <span className="flex items-center gap-1 font-bold text-slate-800">
                  <Star size={16} className="text-yellow-500 fill-yellow-500" /> 
                  {supplier.averageRating ? `${supplier.averageRating} (${supplier.totalReviews} reviews)` : "No reviews yet"}
                </span>
                <span className="flex items-center gap-1"><MapPin size={14} /> {displayLocation}</span>
                <span className="flex items-center gap-1"><Clock size={14} /> {displayReplyTime}</span>
              </div>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto shrink-0">
            <button
              onClick={handleFavoriteToggle}
              className="flex-1 sm:flex-none px-4 py-2.5 bg-white border border-slate-300 text-slate-700 text-sm font-bold rounded hover:bg-slate-50 transition-colors shadow-sm flex items-center justify-center gap-2"
            >
              <Heart size={16} className={favorites.some((f: any) => f.supplier?._id === id || f.supplier === id) ? "fill-red-500 text-red-500" : ""} />
              {favorites.some((f: any) => f.supplier?._id === id || f.supplier === id) ? "Saved" : "Save"}
            </button>
            {supplier.contactInfo?.website && (
              <a href={supplier.contactInfo.website} target="_blank" rel="noreferrer" className="flex-1 sm:flex-none px-6 py-2.5 bg-white border border-slate-300 text-slate-700 text-sm font-bold rounded hover:bg-slate-50 transition-colors shadow-sm flex items-center justify-center gap-2">
                Visit Website <ExternalLink size={14} />
              </a>
            )}
            <Link href={`/suppliers/${supplier._id}/rfq`} className="flex-1 sm:flex-none px-6 py-2.5 bg-[#1b2b3a] hover:bg-slate-800 text-white text-sm font-bold rounded transition-colors shadow-sm flex items-center justify-center gap-2">
              <FileText size={16} /> Send RFQ
            </Link>
          </div>
        </div>

        {/* 2-Column Main Content */}
        <div className="flex flex-col lg:flex-row gap-6 mb-12">

          {/* Left Column (Main Info) */}
          <div className="flex-1 flex flex-col gap-6">

            {/* About */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 sm:p-8">
              <h2 className="text-lg font-bold text-[#1b2b3a] mb-4">About the Company</h2>
              <div className="text-sm text-slate-600 leading-relaxed whitespace-pre-wrap">
                {displayAbout}
              </div>
            </div>

            {/* Products & Services */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 sm:p-8">
              <h2 className="text-lg font-bold text-[#1b2b3a] mb-6">Products & Services</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {displayServices.map((service: any, idx: number) => (
                  <div key={idx} className="bg-slate-50 border border-slate-100 rounded-lg p-5 flex gap-4 hover:border-slate-200 transition-colors">
                    <div className="w-8 h-8 rounded bg-white shadow-sm flex items-center justify-center shrink-0 text-slate-700">
                      {service.icon}
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-800 text-sm mb-1">{service.title}</h3>
                      <p className="text-xs text-slate-500 leading-relaxed">{service.desc}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Gallery */}
            {displayGallery.length > 0 && (
              <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 sm:p-8">
                <h2 className="text-lg font-bold text-[#1b2b3a] mb-6">Gallery</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {displayGallery.map((img: string, idx: number) => (
                    <div key={idx} className="rounded-lg overflow-hidden h-[200px] bg-slate-100 group relative border border-slate-100">
                      <img
                        src={img}
                        alt={`Gallery image ${idx + 1}`}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                      />
                      <div className="absolute inset-0 bg-black/10 group-hover:bg-transparent transition-colors duration-300"></div>
                    </div>
                  ))}
                </div>
              </div>
            )}

          </div>

          {/* Right Column (Sidebar) */}
          <div className="w-full lg:w-[380px] shrink-0 flex flex-col gap-6">

            {/* Contact Information */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 sm:p-8">
              <h2 className="text-lg font-bold text-[#1b2b3a] mb-6">Contact Information</h2>

              <div className="flex flex-col gap-6">
                <div className="flex items-start gap-4">
                  <div className="text-[#dca12f] mt-0.5"><Phone size={18} /></div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Phone</p>
                    <p className="text-sm font-medium text-slate-800">{supplier.contactPhone || "N/A"}</p>
                  </div>
                </div>

                <div className="flex items-start gap-4">
                  <div className="text-[#dca12f] mt-0.5"><Mail size={18} /></div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Email</p>
                    <p className="text-sm font-medium text-[#1b2b3a] hover:underline cursor-pointer">{supplier.contactEmail || "N/A"}</p>
                  </div>
                </div>

                <div className="flex items-start gap-4">
                  <div className="text-[#dca12f] mt-0.5"><Building2 size={18} /></div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Address</p>
                    <p className="text-sm font-medium text-slate-800 whitespace-pre-wrap leading-relaxed">{displayLocation}</p>
                  </div>
                </div>
              </div>

              {/* Map View */}
              {supplier.location?.coordinates && (supplier.location.coordinates[0] !== 0 || supplier.location.coordinates[1] !== 0) && (
                <div className="mt-6 rounded-lg overflow-hidden border border-slate-200 h-[250px] relative">
                  <DynamicMap suppliers={[supplier]} />
                </div>
              )}
            </div>

            {/* Business Details */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 sm:p-8">
              <h2 className="text-lg font-bold text-[#1b2b3a] mb-6">Business Details</h2>

              <div className="flex flex-col gap-4 text-sm">
                <div className="flex justify-between items-center py-2 border-b border-slate-50">
                  <span className="text-slate-500">Established</span>
                  <span className="font-bold text-slate-800">{supplier.establishedYear || "N/A"}</span>
                </div>
                <div className="flex justify-between items-center py-2 border-b border-slate-50">
                  <span className="text-slate-500">Employees</span>
                  <span className="font-bold text-slate-800">{supplier.employeeCount || "N/A"}</span>
                </div>
                <div className="flex justify-between items-center py-2">
                  <span className="text-slate-500">Annual Turnover</span>
                  <span className="font-bold text-slate-800">{supplier.annualTurnover || "N/A"}</span>
                </div>
              </div>

              {supplier.certifications && supplier.certifications.length > 0 && (
                <div className="mt-6">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Certifications</p>
                  <div className="flex flex-wrap gap-2">
                    {supplier.certifications.map((cert: string) => (
                      <span key={cert} className="px-3 py-1.5 bg-slate-50 border border-slate-200 text-slate-700 font-bold text-[11px] rounded-md flex items-center gap-1.5">
                        <div className="w-1.5 h-1.5 rounded-full bg-[#dca12f]"></div> {cert}
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Categories */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 sm:p-8">
              <h2 className="text-lg font-bold text-[#1b2b3a] mb-6">Categories</h2>
              <div className="flex flex-wrap gap-2">
                {supplier.categories?.map((cat: any) => (
                  <span key={cat._id} className="px-3 py-1.5 bg-blue-50/50 border border-blue-100 text-blue-800 font-medium text-[12px] rounded-lg">
                    {cat.name}
                  </span>
                ))}
              </div>
            </div>

          </div>
        </div>
        
        {/* Reviews Section */}
        {reviews.length > 0 && (
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 sm:p-8 mb-12">
            <h2 className="text-xl font-black text-[#1b2b3a] mb-6 flex items-center gap-2">
              <Star size={24} className="text-yellow-500 fill-yellow-500" /> Supplier Reviews ({supplier.totalReviews})
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {reviews.map((review: any) => (
                <div key={review._id} className="bg-slate-50 border border-slate-100 rounded-xl p-6">
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-slate-200 rounded-full flex items-center justify-center text-slate-500 font-bold">
                        {review.buyer?.name?.charAt(0) || "B"}
                      </div>
                      <div>
                        <h4 className="font-bold text-[#1b2b3a] text-sm">{review.buyer?.name || "Verified Buyer"}</h4>
                        <p className="text-xs text-slate-500">{new Date(review.createdAt).toLocaleDateString()}</p>
                      </div>
                    </div>
                    <div className="flex gap-0.5">
                      {[...Array(5)].map((_, i) => (
                        <Star key={i} size={14} className={i < review.rating ? "text-yellow-500 fill-yellow-500" : "text-slate-300"} />
                      ))}
                    </div>
                  </div>
                  <p className="text-sm text-slate-700 leading-relaxed italic">"{review.comment}"</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Bottom CTA Banner */}
        <div className="w-full bg-[#dca12f] rounded-2xl p-8 sm:p-12 flex flex-col md:flex-row items-center justify-between gap-8 shadow-lg shadow-[#dca12f]/20">
          <div className="text-center md:text-left max-w-2xl">
            <h2 className="text-2xl sm:text-3xl font-black text-[#1b2b3a] tracking-tight mb-3">
              Need a custom quote from {supplier.companyName}?
            </h2>
            <p className="text-[#1b2b3a]/80 font-medium text-sm sm:text-base">
              Connect directly with their sales team to discuss bulk pricing, technical specifications, and delivery timelines for your next project.
            </p>
          </div>
          <Link href={`/suppliers/${supplier._id}/rfq`} className="px-8 py-4 bg-[#1b2b3a] hover:bg-slate-900 text-white font-bold rounded-lg transition-colors shadow-xl shrink-0 flex items-center gap-2 group">
            Send RFQ Now <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
          </Link>
        </div>

      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { 
  CheckCircle2, 
  MapPin, 
  Building2, 
  Clock, 
  ExternalLink, 
  MessageSquare, 
  Send, 
  UploadCloud,
  FileText,
  ChevronLeft,
  Check,
  Eye,
  GitBranch,
  X
} from "lucide-react";
import MessageSupplierModal from "@/components/suppliers/MessageSupplierModal";

// Mock data (same as the supplier profile page for consistency)
const mockSupplier = {
  id: "1",
  name: "Steel Company A",
  verified: true,
  isGold: true,
  location: "New York, USA",
  distance: "12 miles away",
  replyTime: "Replies in 2 hours",
  responseAvg: "Replies in 2 hours",
  businessType: "Manufacturer, Distributor",
  coreServices: "Structural Steel, Hot Rolled",
  categories: ["Manufacturer", "Distributor"],
  services: [
    { title: "Structural Steel" },
    { title: "Hot Rolled" },
    { title: "Custom Fabrication" },
    { title: "Raw Steel Coils" }
  ]
};

import { useCreateRfqMutation, useGetRfqUploadUrlMutation } from "@/store/api/rfqApi";
import { useGetSupplierByIdQuery } from "@/store/api/supplierApi";
import { useSelector } from "react-redux";

export default function SendRFQPage({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = React.use(params);
  
  const { data, isLoading } = useGetSupplierByIdQuery(resolvedParams.id, { skip: !resolvedParams.id });
  const backendSupplier = data?.data;

  // Combine real supplier with fallbacks for UI
  const supplier = backendSupplier ? {
    ...mockSupplier,
    id: backendSupplier._id,
    name: backendSupplier.companyName,
    businessType: backendSupplier.categories?.map((c: any) => c.name).join(", ") || mockSupplier.businessType,
    coreServices: backendSupplier.services?.map((s: any) => s.name || s.title).join(", ") || mockSupplier.coreServices,
    responseAvg: "Replies in 24 hours",
    verified: backendSupplier.isApproved,
    location: backendSupplier.contactInfo?.address || "Global",
    distance: ""
  } : mockSupplier;

  const { user } = useSelector((state: any) => state.auth || {});
  
  const [formData, setFormData] = useState({
    buyerName: user?.name || "",
    buyerEmail: user?.email || "",
    buyerPhone: "",
    productNeeded: "",
    quantity: "",
    unit: "Units",
    expectedDelivery: "",
    additionalNotes: ""
  });

  const [createRfq, { isLoading: isSubmitting }] = useCreateRfqMutation();
  const [getRfqUploadUrl] = useGetRfqUploadUrlMutation();
  const [isMessageModalOpen, setIsMessageModalOpen] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [attachments, setAttachments] = useState<File[]>([]);
  const [isUploading, setIsUploading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setIsUploading(true);
      let attachmentUrls: string[] = [];
      
      // Upload files sequentially
      for (const file of attachments) {
        const res = await getRfqUploadUrl({ contentType: file.type }).unwrap();
        const { uploadUrl, fileUrl } = res.data;
        
        await fetch(uploadUrl, {
          method: "PUT",
          body: file,
          headers: { "Content-Type": file.type }
        });
        
        attachmentUrls.push(fileUrl);
      }
      setIsUploading(false);

      await createRfq({
        supplierId: supplier.id,
        buyerName: formData.buyerName,
        buyerEmail: formData.buyerEmail,
        buyerPhone: formData.buyerPhone,
        subject: `RFQ: ${formData.productNeeded}`,
        details: `Unit: ${formData.unit}\nExpected Delivery: ${formData.expectedDelivery}\nNotes: ${formData.additionalNotes}`,
        quantity: Number(formData.quantity),
        attachments: attachmentUrls
      }).unwrap();
      setIsSuccess(true);
    } catch (err) {
      console.error("Failed to send RFQ", err);
      setIsUploading(false);
      alert("Failed to send RFQ. Please try again.");
    }
  };

  if (isLoading) return <div className="min-h-screen flex items-center justify-center">Loading...</div>;

  if (isSuccess) {
    return (
      <div className="min-h-screen bg-[#F8FAFC] flex flex-col items-center justify-center p-4 py-12">
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 sm:p-12 w-full max-w-4xl">
          
          {/* Header */}
          <div className="flex flex-col items-center text-center">
            <div className="w-16 h-16 bg-[#dca12f] rounded-2xl flex items-center justify-center mb-6 shadow-sm">
              <CheckCircle2 size={32} className="text-[#1b2b3a]" />
            </div>
            <h1 className="text-3xl sm:text-4xl font-black text-[#1b2b3a] tracking-tight mb-4 max-w-xl">
              Your RFQ has been sent successfully.
            </h1>
            <p className="text-slate-500 font-medium text-lg max-w-2xl">
              {supplier.name} has received your request and can respond directly with pricing, availability, and delivery details.
            </p>
          </div>

          {/* Details Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-12">
            
            {/* RFQ Details */}
            <div className="bg-[#FAFAFA] border border-slate-100 rounded-xl p-6 sm:p-8">
              <h3 className="text-xl font-bold text-[#1b2b3a] flex items-center gap-2 mb-6">
                <FileText size={20} className="text-emerald-700" /> RFQ Details
              </h3>
              <div className="flex flex-col gap-4 text-sm">
                <div className="flex justify-between items-center py-2 border-b border-slate-200/60">
                  <span className="font-bold text-slate-500">Supplier</span>
                  <span className="font-bold text-[#1b2b3a] text-right">{supplier.name}</span>
                </div>
                <div className="flex justify-between items-center py-2 border-b border-slate-200/60">
                  <span className="font-bold text-slate-500">Product</span>
                  <span className="font-bold text-[#1b2b3a] text-right">{formData.productNeeded || "-"}</span>
                </div>
                <div className="flex justify-between items-center py-2 border-b border-slate-200/60">
                  <span className="font-bold text-slate-500">Quantity</span>
                  <span className="font-bold text-[#1b2b3a] text-right">{formData.quantity} {formData.unit}</span>
                </div>
                <div className="flex justify-between items-center py-2 border-b border-slate-200/60">
                  <span className="font-bold text-slate-500">Deadline</span>
                  <span className="font-bold text-[#1b2b3a] text-right">
                    {formData.expectedDelivery ? new Date(formData.expectedDelivery).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : "-"}
                  </span>
                </div>
                <div className="flex justify-between items-center py-2">
                  <span className="font-bold text-slate-500">Status</span>
                  <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-xs font-bold text-right">
                    <span className="w-1.5 h-1.5 rounded-full bg-blue-600"></span>
                    Pending Supplier Response
                  </span>
                </div>
              </div>
            </div>

            {/* What happens next? */}
            <div className="bg-[#FAFAFA] border border-slate-100 rounded-xl p-6 sm:p-8 relative">
              <h3 className="text-xl font-bold text-[#1b2b3a] flex items-center gap-2 mb-6">
                <GitBranch size={20} className="text-emerald-700" /> What happens next?
              </h3>
              
              <div className="relative border-l-2 border-slate-200 ml-3 space-y-6 pb-2">
                <div className="relative pl-6">
                  <div className="absolute w-3 h-3 bg-blue-600 rounded-full -left-[7px] top-1.5 ring-4 ring-[#FAFAFA]"></div>
                  <h4 className="font-black text-[#1b2b3a] text-sm mb-1">1. Review</h4>
                  <p className="text-xs font-medium text-slate-500 leading-relaxed">Supplier reviews your requirements and specifications.</p>
                </div>
                <div className="relative pl-6">
                  <div className="absolute w-3 h-3 bg-slate-200 rounded-full -left-[7px] top-1.5 ring-4 ring-[#FAFAFA]"></div>
                  <h4 className="font-bold text-slate-700 text-sm mb-1">2. Response</h4>
                  <p className="text-xs font-medium text-slate-500 leading-relaxed">You receive a formal quote via email and dashboard.</p>
                </div>
                <div className="relative pl-6">
                  <div className="absolute w-3 h-3 bg-slate-200 rounded-full -left-[7px] top-1.5 ring-4 ring-[#FAFAFA]"></div>
                  <h4 className="font-bold text-slate-700 text-sm mb-1">3. Negotiate</h4>
                  <p className="text-xs font-medium text-slate-500 leading-relaxed">Discuss terms and finalize the transaction securely.</p>
                </div>
              </div>
            </div>

          </div>

          {/* Action Buttons */}
          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 mt-12 pt-8 border-t border-slate-100">
            <Link 
              href="/dashboard/rfqs"
              className="w-full sm:w-auto px-6 py-3 bg-[#1b2b3a] hover:bg-[#2a4054] text-white text-sm font-bold rounded-lg transition-colors flex items-center justify-center gap-2 shadow-sm"
            >
              <Eye size={18} /> View RFQ Status
            </Link>
            <button 
              onClick={() => setIsMessageModalOpen(true)}
              className="w-full sm:w-auto px-6 py-3 bg-[#dca12f] hover:bg-[#c99126] text-slate-900 text-sm font-bold rounded-lg transition-colors flex items-center justify-center gap-2 shadow-sm"
            >
              <MessageSquare size={18} /> Message Supplier
            </button>
            <Link 
              href="/suppliers"
              className="w-full sm:w-auto px-6 py-3 bg-white border border-slate-300 text-[#1b2b3a] hover:bg-slate-50 text-sm font-bold rounded-lg transition-colors flex items-center justify-center shadow-sm"
            >
              Continue Browsing
            </Link>
          </div>

        </div>

        <MessageSupplierModal 
          isOpen={isMessageModalOpen}
          onClose={() => setIsMessageModalOpen(false)}
          supplier={supplier}
        />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-20">
      <div className="max-w-[1280px] mx-auto px-4 sm:px-6 py-8">
        
        {/* Back Navigation */}
        <Link href={`/suppliers/${resolvedParams.id}`} className="inline-flex items-center gap-1 text-sm font-medium text-slate-500 hover:text-slate-800 mb-6 transition-colors">
          <ChevronLeft size={16} /> Back to Supplier Profile
        </Link>

        {/* Page Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-black text-[#1b2b3a] tracking-tight mb-2">Send RFQ</h1>
          <p className="text-slate-500 text-sm font-medium">Request pricing, availability, and delivery details directly from the supplier.</p>
        </div>

        <div className="flex flex-col lg:flex-row gap-6">
          
          {/* Main Form Area */}
          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 p-6 sm:p-8">
            <h2 className="text-xl font-bold text-[#1b2b3a] mb-6">Request for Quotation</h2>
            
            <div className="flex items-center gap-2 mb-8">
              <span className="text-sm font-medium text-slate-500">To:</span>
              <div className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-blue-50 text-blue-700 rounded-full text-sm font-bold border border-blue-100">
                {supplier.name}
                {supplier.verified && <CheckCircle2 size={14} className="text-blue-600 fill-blue-100" />}
              </div>
            </div>

            <form className="flex flex-col gap-6" onSubmit={handleSubmit}>
              {/* Buyer Information (For Guests or Logged In Users) */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div>
                  <label className="block text-sm font-bold text-[#1b2b3a] mb-2">Your Name <span className="text-red-500">*</span></label>
                  <input 
                    type="text" 
                    required
                    value={formData.buyerName}
                    onChange={(e) => setFormData({...formData, buyerName: e.target.value})}
                    placeholder="e.g., John Doe" 
                    className="w-full px-4 py-3 rounded-lg border border-slate-200 bg-slate-50 text-black focus:bg-white focus:outline-none focus:ring-2 focus:ring-[#dca12f]/50 focus:border-[#dca12f] transition-colors text-sm"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-[#1b2b3a] mb-2">Your Email <span className="text-red-500">*</span></label>
                  <input 
                    type="email" 
                    required
                    value={formData.buyerEmail}
                    onChange={(e) => setFormData({...formData, buyerEmail: e.target.value})}
                    placeholder="e.g., john@example.com" 
                    className="w-full px-4 py-3 rounded-lg border border-slate-200 bg-slate-50 text-black focus:bg-white focus:outline-none focus:ring-2 focus:ring-[#dca12f]/50 focus:border-[#dca12f] transition-colors text-sm"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-[#1b2b3a] mb-2">Phone Number</label>
                  <input 
                    type="text" 
                    value={formData.buyerPhone}
                    onChange={(e) => setFormData({...formData, buyerPhone: e.target.value})}
                    placeholder="e.g., +1 234 567 890" 
                    className="w-full px-4 py-3 rounded-lg border border-slate-200 bg-slate-50 text-black focus:bg-white focus:outline-none focus:ring-2 focus:ring-[#dca12f]/50 focus:border-[#dca12f] transition-colors text-sm"
                  />
                </div>
              </div>

              {/* Product / Service */}
              <div>
                <label className="block text-sm font-bold text-[#1b2b3a] mb-2">Product/Service Needed <span className="text-red-500">*</span></label>
                <input 
                  type="text" 
                  required
                  value={formData.productNeeded}
                  onChange={(e) => setFormData({...formData, productNeeded: e.target.value})}
                  placeholder="e.g., Hot Rolled Steel Coils, ASTM A36" 
                  className="w-full px-4 py-3 rounded-lg border border-slate-200 bg-slate-50 text-black focus:bg-white focus:outline-none focus:ring-2 focus:ring-[#dca12f]/50 focus:border-[#dca12f] transition-colors text-sm"
                />
              </div>

              {/* Quantity & Date Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-bold text-[#1b2b3a] mb-2">Quantity <span className="text-red-500">*</span></label>
                  <div className="flex">
                    <input 
                      type="number" 
                      required
                      min="1"
                      value={formData.quantity}
                      onChange={(e) => setFormData({...formData, quantity: e.target.value})}
                      placeholder="e.g., 500" 
                      className="w-full flex-1 px-4 py-3 rounded-l-lg border border-slate-200 bg-slate-50 text-black focus:bg-white focus:outline-none focus:ring-2 focus:ring-[#dca12f]/50 focus:border-[#dca12f] transition-colors text-sm"
                    />
                    <select 
                      value={formData.unit}
                      onChange={(e) => setFormData({...formData, unit: e.target.value})}
                      className="px-4 py-3 rounded-r-lg border-y border-r border-slate-200 bg-slate-50 text-black text-sm focus:outline-none focus:ring-2 focus:ring-[#dca12f]/50 focus:border-[#dca12f] transition-colors cursor-pointer border-l shrink-0"
                    >
                      <option>Units</option>
                      <option>Tons</option>
                      <option>Kg</option>
                      <option>Pieces</option>
                      <option>Meters</option>
                    </select>
                  </div>
                </div>
                
                <div>
                  <label className="block text-sm font-bold text-[#1b2b3a] mb-2">Expected Delivery/Deadline <span className="text-red-500">*</span></label>
                  <div className="relative">
                    <input 
                      type="date" 
                      required
                      value={formData.expectedDelivery}
                      onChange={(e) => setFormData({...formData, expectedDelivery: e.target.value})}
                      className="w-full px-4 py-3 rounded-lg border border-slate-200 bg-slate-50 text-black focus:bg-white focus:outline-none focus:ring-2 focus:ring-[#dca12f]/50 focus:border-[#dca12f] transition-colors text-sm"
                    />
                  </div>
                </div>
              </div>

              {/* Additional Notes */}
              <div>
                <label className="block text-sm font-bold text-[#1b2b3a] mb-2">Additional Notes / Specifications</label>
                <textarea 
                  rows={4}
                  value={formData.additionalNotes}
                  onChange={(e) => {
                    setFormData({...formData, additionalNotes: e.target.value});
                    e.target.style.height = 'auto';
                    e.target.style.height = `${e.target.scrollHeight}px`;
                  }}
                  placeholder="Provide any specific requirements, tolerances, or shipping instructions..." 
                  className="w-full px-4 py-3 rounded-lg border border-slate-200 bg-slate-50 text-black focus:bg-white focus:outline-none focus:ring-2 focus:ring-[#dca12f]/50 focus:border-[#dca12f] transition-colors text-sm resize-none overflow-hidden"
                ></textarea>
              </div>

              {/* Attachments */}
              <div>
                <label className="block text-sm font-bold text-[#1b2b3a] mb-2">Attachments (Optional)</label>
                <div 
                  className="border-2 border-dashed border-slate-200 rounded-xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer p-8 flex flex-col items-center justify-center text-center group relative"
                >
                  <input 
                    type="file" 
                    multiple
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    onChange={(e) => {
                      if (e.target.files) {
                        setAttachments([...attachments, ...Array.from(e.target.files)]);
                      }
                    }}
                  />
                  <div className="w-12 h-12 rounded-full bg-white shadow-sm flex items-center justify-center mb-4 text-slate-400 group-hover:text-[#dca12f] group-hover:scale-110 transition-all">
                    <UploadCloud size={24} />
                  </div>
                  <p className="text-sm font-bold text-[#1b2b3a] mb-1">Drag & drop files here</p>
                  <p className="text-xs text-slate-500 mb-4">or click to browse from your computer</p>
                  <p className="text-[11px] font-medium text-slate-400 uppercase tracking-wider">Supported formats: PDF, DOCX, XLSX, JPG, PNG (Max 20MB)</p>
                </div>
                
                {attachments.length > 0 && (
                  <div className="mt-4 space-y-2">
                    {attachments.map((file, idx) => (
                      <div key={idx} className="flex items-center justify-between p-3 bg-white border border-slate-200 rounded-lg shadow-sm">
                        <div className="flex items-center gap-3">
                          <FileText size={16} className="text-[#dca12f]" />
                          <span className="text-sm font-medium text-slate-700">{file.name}</span>
                        </div>
                        <button 
                          type="button" 
                          onClick={() => setAttachments(attachments.filter((_, i) => i !== idx))}
                          className="text-slate-400 hover:text-red-500 transition-colors"
                        >
                          <X size={16} />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {/* Form Actions */}
              <div className="flex items-center justify-end gap-4 mt-4 pt-6 border-t border-slate-100">
                <Link 
                  href={`/suppliers/${resolvedParams.id}`}
                  className="px-6 py-2.5 bg-white border border-slate-300 text-slate-700 text-sm font-bold rounded hover:bg-slate-50 transition-colors shadow-sm"
                >
                  Cancel
                </Link>
                <button 
                  type="submit"
                  disabled={isSubmitting || isUploading}
                  className="px-6 py-2.5 bg-[#dca12f] hover:bg-[#c99126] text-slate-900 text-sm font-bold rounded transition-colors shadow-sm flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                >
                  <Send size={16} /> {isSubmitting || isUploading ? "Submitting..." : "Submit RFQ"}
                </button>
              </div>
            </form>
          </div>

          {/* Right Sidebar */}
          <div className="w-full lg:w-[380px] shrink-0 flex flex-col gap-6">
            
            {/* Supplier Summary Card */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 sm:p-8">
              <div className="flex items-start gap-4 mb-6">
                <div className="w-12 h-12 rounded bg-slate-100 flex items-center justify-center shrink-0 border border-slate-200">
                   <Building2 className="text-slate-500" size={24} />
                </div>
                <div>
                  <h3 className="font-bold text-[#1b2b3a] text-lg leading-tight flex items-center gap-1.5 mb-1">
                    {supplier.name}
                  </h3>
                  {supplier.verified && (
                    <span className="flex items-center gap-1 text-[11px] font-bold text-blue-600 uppercase tracking-wider">
                      <CheckCircle2 size={12} className="fill-blue-100" /> Verified Supplier
                    </span>
                  )}
                </div>
              </div>

              <div className="flex flex-col gap-4 text-sm mb-8">
                <div className="flex items-start gap-3">
                  <MapPin size={16} className="text-slate-400 mt-0.5 shrink-0" />
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-0.5">Location</p>
                    <p className="font-medium text-slate-700">{supplier.location} <span className="text-blue-500 font-normal">({supplier.distance})</span></p>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <Building2 size={16} className="text-slate-400 mt-0.5 shrink-0" />
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-0.5">Business Type</p>
                    <p className="font-medium text-slate-700">{supplier.businessType}</p>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <FileText size={16} className="text-slate-400 mt-0.5 shrink-0" />
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-0.5">Core Services</p>
                    <p className="font-medium text-slate-700">{supplier.coreServices}</p>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <Clock size={16} className="text-slate-400 mt-0.5 shrink-0" />
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-0.5">Avg. Response Time</p>
                    <p className="font-medium text-slate-700">{supplier.responseAvg}</p>
                  </div>
                </div>
              </div>

              <div className="flex flex-col gap-3">
                <button className="w-full py-2.5 bg-white border border-slate-300 text-[#1b2b3a] text-sm font-bold rounded hover:bg-slate-50 transition-colors flex items-center justify-center gap-2">
                  <ExternalLink size={16} /> Visit Company Website
                </button>
                <button 
                  onClick={() => setIsMessageModalOpen(true)}
                  className="w-full py-2.5 bg-blue-50 text-blue-700 hover:bg-blue-100 text-sm font-bold rounded transition-colors flex items-center justify-center gap-2"
                >
                  <MessageSquare size={16} /> Message Supplier
                </button>
              </div>
            </div>

            {/* Info Card */}
            <div className="bg-slate-50 rounded-xl border border-slate-200 p-6 sm:p-8">
              <h3 className="font-bold text-[#1b2b3a] flex items-center gap-2 mb-4">
                <Clock size={18} className="text-[#dca12f]" /> What happens next?
              </h3>
              <ul className="space-y-4 text-sm text-slate-600">
                <li className="flex items-start gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 mt-1.5 shrink-0"></span>
                  <p>Your RFQ is sent securely to the supplier&apos;s verified contacts.</p>
                </li>
                <li className="flex items-start gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 mt-1.5 shrink-0"></span>
                  <p>You will receive an email notification when they review or reply to your request.</p>
                </li>
                <li className="flex items-start gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 mt-1.5 shrink-0"></span>
                  <p>Manage all your quotes and communications from your WULFARA Dashboard.</p>
                </li>
              </ul>
            </div>

          </div>
        </div>

      </div>

      <MessageSupplierModal 
        isOpen={isMessageModalOpen}
        onClose={() => setIsMessageModalOpen(false)}
        supplier={supplier}
      />
    </div>
  );
}

"use client";

import React, { useMemo, useState } from "react";
import Link from "next/link";
import { Search, MapPin, ChevronDown, Map, ChevronLeft, ChevronRight } from "lucide-react";
import SupplierHero from "@/components/suppliers/SupplierHero";
import ServiceTypeGrid from "@/components/suppliers/ServiceTypeGrid";
import SupplierFilters from "@/components/suppliers/SupplierFilters";
import SupplierCard, { SupplierData } from "@/components/suppliers/SupplierCard";
import { useGetSuppliersQuery } from "@/store/api/supplierApi";

export default function ServiceSuppliersPage() {
  const { data, isLoading } = useGetSuppliersQuery("");
  const suppliers = data?.data || [];
  const [activeFilters, setActiveFilters] = useState<{ certifications: string[]; companySize: string }>({
    certifications: [],
    companySize: "",
  });
  const [topFilters, setTopFilters] = useState({
    query: "",
    location: "",
    type: "Manufacturing Type",
    distance: "Distance",
  });
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 6;

  const handleFilterChange = (type: string, value: string) => {
    if (type === "certification") {
      setActiveFilters((prev) => {
        const certs = prev.certifications.includes(value)
          ? prev.certifications.filter((c) => c !== value)
          : [...prev.certifications, value];
        return { ...prev, certifications: certs };
      });
    } else if (type === "companySize") {
      setActiveFilters((prev) => ({
        ...prev,
        companySize: prev.companySize === value ? "" : value,
      }));
    }
    setCurrentPage(1);
  };

  const mappedSuppliers = useMemo<SupplierData[]>(
    () =>
      suppliers.map((supplier: any) => ({
        id: supplier._id,
        name: supplier.companyName,
        verified: supplier.isApproved,
        location: supplier.location?.formattedAddress || "Location not specified",
        distance: supplier.serviceAreas?.[0] || "Global coverage",
        response: supplier.avgResponseTime || "Replies in ~24 Hours",
        rating: supplier.averageRating || 0,
        reviews: supplier.totalReviews || 0,
        desc: supplier.description || "Supplier profile is being completed.",
        tags:
          supplier.categories?.map((category: any) => category.name).slice(0, 3) ||
          supplier.coreProducts?.slice(0, 3) ||
          ["Industrial Supplier"],
        certifications: supplier.certifications || [],
        companySize: supplier.employeeCount || "",
      })),
    [suppliers]
  );

  const filteredSuppliers = useMemo(() => {
    let result = [...mappedSuppliers];

    if (topFilters.query) {
      const query = topFilters.query.toLowerCase();
      result = result.filter(
        (supplier) =>
          supplier.name.toLowerCase().includes(query) ||
          supplier.desc.toLowerCase().includes(query) ||
          supplier.tags.some((tag) => tag.toLowerCase().includes(query))
      );
    }

    if (topFilters.location) {
      const location = topFilters.location.toLowerCase();
      result = result.filter((supplier) => supplier.location.toLowerCase().includes(location));
    }

    if (topFilters.type !== "Manufacturing Type") {
      result = result.filter((supplier) => supplier.tags.includes(topFilters.type));
    }

    if (activeFilters.companySize) {
      result = result.filter((supplier) => supplier.companySize === activeFilters.companySize);
    }

    if (activeFilters.certifications.length > 0) {
      result = result.filter((supplier) =>
        activeFilters.certifications.every((cert) => supplier.certifications?.includes(cert))
      );
    }

    return result;
  }, [activeFilters, mappedSuppliers, topFilters]);

  const totalPages = Math.max(1, Math.ceil(filteredSuppliers.length / itemsPerPage));
  const paginatedSuppliers = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    return filteredSuppliers.slice(startIndex, startIndex + itemsPerPage);
  }, [currentPage, filteredSuppliers]);

  return (
    <div className="min-h-screen bg-[#F8FAFC]">
      <SupplierHero />
      <ServiceTypeGrid />

      <div className="max-w-[1280px] mx-auto px-4 sm:px-6 lg:px-8 py-10">
        <div className="flex flex-col lg:flex-row gap-3 mb-8">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input
              type="text"
              placeholder="Company or service..."
              value={topFilters.query}
              onChange={(e) => {
                setTopFilters((prev) => ({ ...prev, query: e.target.value }));
                setCurrentPage(1);
              }}
              className="w-full pl-9 pr-4 py-2.5 bg-white border border-slate-200 rounded text-sm text-slate-900 focus:outline-none focus:border-[#dca12f]"
            />
          </div>
          <div className="relative flex-[0.7]">
            <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input
              type="text"
              placeholder="City, State, ZIP..."
              value={topFilters.location}
              onChange={(e) => {
                setTopFilters((prev) => ({ ...prev, location: e.target.value }));
                setCurrentPage(1);
              }}
              className="w-full pl-9 pr-4 py-2.5 bg-white border border-slate-200 rounded text-sm text-slate-900 focus:outline-none focus:border-[#dca12f]"
            />
          </div>
          <div className="relative flex-[0.8]">
            <select
              value={topFilters.type}
              onChange={(e) => {
                setTopFilters((prev) => ({ ...prev, type: e.target.value }));
                setCurrentPage(1);
              }}
              className="w-full pl-4 pr-10 py-2.5 bg-white border border-slate-200 rounded text-sm text-slate-700 appearance-none focus:outline-none focus:border-[#dca12f]"
            >
              <option value="Manufacturing Type">Manufacturing Type</option>
              {Array.from(new Set(mappedSuppliers.flatMap((supplier) => supplier.tags))).map((tag) => (
                <option key={tag} value={tag}>
                  {tag}
                </option>
              ))}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={16} />
          </div>
          <button className="px-6 py-2.5 bg-[#dca12f] hover:bg-[#c99126] text-slate-900 text-sm font-bold rounded transition-colors shadow-sm shrink-0 whitespace-nowrap">
            Apply Filters
          </button>
          <Link href="/suppliers/map" className="px-5 py-2.5 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 text-sm font-bold rounded transition-colors shadow-sm shrink-0 flex items-center gap-2 whitespace-nowrap">
            <Map size={16} /> Map View
          </Link>
        </div>

        <div className="flex flex-col md:flex-row gap-8">
          <SupplierFilters activeFilters={activeFilters} onFilterChange={handleFilterChange} />

          <div className="flex-1">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-base font-bold text-slate-900">{filteredSuppliers.length} Suppliers Found</h2>
            </div>

            {isLoading ? (
              <div className="py-12 text-center text-slate-500">Loading suppliers...</div>
            ) : paginatedSuppliers.length === 0 ? (
              <div className="py-12 text-center text-slate-500">No listed suppliers match your filters yet.</div>
            ) : (
              <div className="space-y-4">
                {paginatedSuppliers.map((supplier) => (
                  <SupplierCard key={supplier.id} sup={supplier} />
                ))}
              </div>
            )}

            {totalPages > 1 && (
              <div className="flex items-center justify-center gap-2 mt-10">
                <button
                  onClick={() => setCurrentPage((page) => Math.max(1, page - 1))}
                  disabled={currentPage === 1}
                  className="w-8 h-8 rounded border border-slate-200 flex items-center justify-center text-slate-400 hover:bg-slate-50 disabled:opacity-50"
                >
                  <ChevronLeft size={16} />
                </button>

                {[...Array(totalPages)].map((_, index) => (
                  <button
                    key={index}
                    onClick={() => setCurrentPage(index + 1)}
                    className={`w-8 h-8 rounded text-sm font-medium transition-colors ${
                      currentPage === index + 1
                        ? "bg-[#dca12f] text-slate-900 font-bold shadow-sm"
                        : "border border-slate-200 text-slate-600 hover:bg-slate-50"
                    }`}
                  >
                    {index + 1}
                  </button>
                ))}

                <button
                  onClick={() => setCurrentPage((page) => Math.min(totalPages, page + 1))}
                  disabled={currentPage === totalPages}
                  className="w-8 h-8 rounded border border-slate-200 flex items-center justify-center text-slate-600 hover:bg-slate-50 disabled:opacity-50"
                >
                  <ChevronRight size={16} />
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef } from "react";
import { usePathname } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import { useSelector } from "react-redux";
import { RootState } from "@/store/store";
import logoImg from "../../../public/assets/logo.png";
import {
  LayoutDashboard,
  Search,
  Bookmark,
  FileText,
  Mail,
  Settings,
  Plus,
  Menu,
  X,
  Bell,
  Check
} from "lucide-react";
import { io } from "socket.io-client";
import { API_BASE_URL, SOCKET_BASE_URL } from "@/config/urls";

const navItems = [
  { label: "Overview", href: "/dashboard", icon: LayoutDashboard },
  { label: "Search Suppliers", href: "/dashboard/search", icon: Search },
  { label: "Favorite Suppliers", href: "/dashboard/favorites", icon: Bookmark },
  { label: "My RFQs", href: "/dashboard/rfqs", icon: FileText },
  { label: "Messages", href: "/dashboard/messages", icon: Mail },
  { label: "Profile Settings", href: "/dashboard/settings", icon: Settings },
];

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const { user } = useSelector((state: RootState) => state.auth);
  const [isGuestMode, setIsGuestMode] = useState(false);

  const [notifications, setNotifications] = useState<any[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setIsGuestMode(localStorage.getItem("guestMode") === "true");

    // Click outside to close notifications
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (!user || !user._id) return;
    
    // Fetch initial notifications
    const fetchNotifications = async () => {
      try {
        const token = localStorage.getItem("token") || (typeof window !== 'undefined' ? (window.localStorage.getItem('token') || '') : '');
        const res = await fetch(`${API_BASE_URL}/notifications`, {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        const data = await res.json();
        if (data.success) {
          setNotifications(data.data);
          setUnreadCount(data.data.filter((n: any) => !n.isRead).length);
        }
      } catch (err) {
        console.error("Error fetching notifications:", err);
      }
    };
    
    fetchNotifications();

    // Socket.io connection
    const socket = io(SOCKET_BASE_URL);
    
    socket.emit("join_room", user._id);
    
    socket.on("new_notification", (newNotification) => {
      setNotifications(prev => [newNotification, ...prev]);
      setUnreadCount(prev => prev + 1);
    });

    return () => {
      socket.disconnect();
    };
  }, [user]);

  const markAllAsRead = async () => {
    if (isGuestMode) return;

    try {
      const token = localStorage.getItem("token") || '';
      const res = await fetch(`${API_BASE_URL}/notifications/read-all`, {
        method: "PATCH",
        headers: {
          Authorization: `Bearer ${token}`
        }
      });
      const data = await res.json();
      if (data.success) {
        setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
        setUnreadCount(0);
      }
    } catch (err) {
      console.error("Error marking all as read:", err);
    }
  };

  const markAsRead = async (id: string) => {
    if (isGuestMode) return;

    try {
      const token = localStorage.getItem("token") || '';
      const res = await fetch(`${API_BASE_URL}/notifications/${id}/read`, {
        method: "PATCH",
        headers: {
          Authorization: `Bearer ${token}`
        }
      });
      const data = await res.json();
      if (data.success) {
        setNotifications(prev => prev.map(n => n._id === id ? { ...n, isRead: true } : n));
        setUnreadCount(prev => Math.max(0, prev - 1));
      }
    } catch (err) {
      console.error("Error marking as read:", err);
    }
  };

  return (
    <div className="flex h-screen bg-[#F8F9FB] overflow-hidden">
      {/* ── Mobile Sidebar Overlay ── */}
      {isMobileMenuOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40 md:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      {/* ── Sidebar ── */}
      <aside
        className={`fixed inset-y-0 left-0 z-50 w-[260px] bg-[#F2F5F9] border-r border-gray-200 flex flex-col transform transition-transform duration-200 ease-in-out md:relative md:translate-x-0 ${isMobileMenuOpen ? "translate-x-0" : "-translate-x-full"
          }`}
      >
        {/* Logo */}
        <div className="px-6 pt-8 pb-8 flex items-center justify-between">
          <Link href="/" className="flex items-center gap-3">
            <Image src={logoImg} alt="WULFARA" width={28} height={28} />
            <span className="text-[20px] font-extrabold tracking-tight text-[#0B172E]">
              WULFARA
            </span>
          </Link>
          <button
            className="md:hidden text-gray-500 hover:text-gray-700"
            onClick={() => setIsMobileMenuOpen(false)}
          >
            <X size={20} />
          </button>
        </div>

        {/* User info */}
        <div className="px-6 pb-6">
          <div className="flex items-center gap-3">
            <img src={`https://ui-avatars.com/api/?name=${user?.name || "Guest Buyer"}&background=212E46&color=fff`} alt={user?.name || "Guest Buyer"} className="w-10 h-10 rounded-lg object-cover shadow-sm border border-gray-200" />
            <div>
              <p className="text-[14px] font-bold text-[#0B172E] leading-tight truncate w-[150px]">
                {user?.name || (isGuestMode ? "Guest Buyer" : "Loading...")}
              </p>
              <p className="text-[12px] font-bold text-gray-500 capitalize">{isGuestMode ? "Guest" : user?.role || "buyer"} Account</p>
            </div>
          </div>
        </div>

        {/* New RFQ button */}
        <div className="px-6 pb-6">
          <Link
            href="/dashboard/rfqs/new"
            className="flex items-center justify-center gap-2 w-full py-2.5 rounded-md bg-[#212E46] hover:bg-[#151D2C] text-white text-[14px] font-semibold transition-colors shadow-sm"
          >
            <Plus size={18} strokeWidth={2.5} />
            New RFQ
          </Link>
        </div>

        {/* Navigation */}
        <nav className="flex-1 px-4 space-y-2 overflow-y-auto">
          {navItems.map((item) => {
            const isActive =
              item.href === "/dashboard"
                ? pathname === "/dashboard"
                : pathname.startsWith(item.href);

            return (
              <Link
                key={item.href}
                href={item.href}
                onClick={() => setIsMobileMenuOpen(false)}
                className={`flex items-center gap-4 px-4 py-3 rounded-md text-[14px] font-bold transition-colors ${isActive
                    ? "bg-[#DFB63E] text-[#0B172E] shadow-sm"
                    : "text-[#4B5563] hover:bg-[#E5E9F0] hover:text-[#0B172E]"
                  }`}
              >
                <item.icon size={20} strokeWidth={isActive ? 2.5 : 2} />
                {item.label}
              </Link>
            );
          })}
        </nav>
      </aside>

      {/* ── Main area ── */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Top Bar */}
        <header className="h-[64px] shrink-0 bg-white border-b border-gray-200 flex items-center justify-between px-4 md:px-8 gap-4">
          <div className="flex items-center gap-3">
            <button
              className="md:hidden text-gray-600 hover:text-gray-900"
              onClick={() => setIsMobileMenuOpen(true)}
            >
              <Menu size={24} />
            </button>
            <h1 className="text-[18px] font-bold text-[#0f1b2d] hidden sm:block">Overview</h1>
          </div>

          <div className="flex items-center gap-2 sm:gap-5 flex-1 justify-end">
            {/* Search */}
            <div className="relative hidden md:block w-full max-w-[320px]">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              />
              <input
                type="text"
                placeholder="Search suppliers, RFQs, messages..."
                className="w-full h-[38px] pl-9 pr-4 text-sm rounded-lg border border-gray-200 bg-[#F8F9FB] focus:outline-none focus:ring-2 focus:ring-[#D4AF37]/30 focus:border-[#D4AF37] placeholder:text-gray-400 transition-all"
              />
            </div>

            {/* Mobile Search Icon */}
            <button className="md:hidden p-2 rounded-lg hover:bg-gray-100 transition-colors">
              <Search size={20} className="text-gray-500" />
            </button>

            {/* Icons */}
            <div className="relative" ref={dropdownRef}>
              <button 
                onClick={() => setShowNotifications(!showNotifications)}
                className="relative p-2 rounded-lg hover:bg-gray-100 transition-colors"
              >
                <Bell size={20} className="text-gray-500" />
                {unreadCount > 0 && (
                  <span className="absolute top-1 right-1 bg-red-500 text-white text-[9px] flex items-center justify-center font-bold h-[14px] min-w-[14px] px-1 rounded-full border border-white">
                    {unreadCount > 99 ? '99+' : unreadCount}
                  </span>
                )}
              </button>

              {/* Notification Dropdown */}
              {showNotifications && (
                <div className="absolute right-0 mt-2 w-72 sm:w-80 bg-white rounded-xl shadow-lg border border-gray-100 overflow-hidden z-50">
                  <div className="p-3 border-b border-gray-100 flex items-center justify-between bg-gray-50/50">
                    <h3 className="font-bold text-[#0B172E] text-[15px]">Notifications</h3>
                    {unreadCount > 0 && (
                      <button 
                        onClick={markAllAsRead}
                        className="text-[12px] text-blue-600 font-semibold hover:text-blue-800"
                      >
                        Mark all as read
                      </button>
                    )}
                  </div>
                  
                  <div className="max-h-[350px] overflow-y-auto">
                    {notifications.length === 0 ? (
                      <div className="p-6 text-center text-sm text-gray-500">
                        No notifications yet.
                      </div>
                    ) : (
                      notifications.map((item) => (
                        <div 
                          key={item._id} 
                          onClick={() => !item.isRead && markAsRead(item._id)}
                          className={`p-3 border-b border-gray-50 hover:bg-gray-50 cursor-pointer flex gap-3 transition-colors ${!item.isRead ? 'bg-blue-50/30' : ''}`}
                        >
                          <div className={`mt-0.5 p-2 rounded-full shrink-0 h-fit ${!item.isRead ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-500'}`}>
                            <Bell size={16} />
                          </div>
                          <div>
                            <p className={`text-[13px] ${!item.isRead ? 'font-bold text-gray-900' : 'font-semibold text-gray-700'}`}>
                              {item.title}
                            </p>
                            <p className={`text-[12px] mt-0.5 ${!item.isRead ? 'text-gray-700' : 'text-gray-500'}`}>
                              {item.message}
                            </p>
                            <p className="text-[10px] text-gray-400 mt-1">
                              {new Date(item.createdAt).toLocaleString()}
                            </p>
                          </div>
                          {!item.isRead && (
                            <div className="shrink-0 mt-1.5">
                              <div className="w-2 h-2 bg-blue-600 rounded-full"></div>
                            </div>
                          )}
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>
            
            <button className="p-2 rounded-lg hover:bg-gray-100 transition-colors">
              <Mail size={20} className="text-gray-500" />
            </button>
          </div>
        </header>

        {/* Page Content */}
        <main className="flex-1 overflow-y-auto p-4 md:p-8">{children}</main>
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from "react";
import { CheckCircle, Paperclip, Send } from "lucide-react";
import { io } from "socket.io-client";
import { useGetMessagesQuery, useSendMessageMutation } from "@/store/features/messages/messagesApi";
import { useSelector } from "react-redux";
import { SOCKET_BASE_URL } from "@/config/urls";

export default function MessageChat({
  activeChat,
  messagesEndRef
}: any) {
  const [inputText, setInputText] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  
  const isNewChat = activeChat.id?.startsWith('new-');
  const queryId = isNewChat ? "skip" : activeChat.id;
  const { data: messagesResponse, isLoading } = useGetMessagesQuery(queryId, { skip: !activeChat.id || isNewChat });
  const [sendMessageApi] = useSendMessageMutation();
  const user = useSelector((state: any) => state.auth?.user || { _id: 'temp_user_id' });

  const [socketMessages, setSocketMessages] = useState<any[]>([]);
  const socketRef = useRef<any>(null);

  const rawMessages = messagesResponse?.data || [];

  useEffect(() => {
    socketRef.current = io(SOCKET_BASE_URL);
    socketRef.current.emit('join_room', activeChat.id);

    socketRef.current.on('receive_message', (newMsg: any) => {
      setSocketMessages((prev) => [...prev, newMsg]);
    });

    return () => {
      socketRef.current.disconnect();
    };
  }, [activeChat.id]);

  const allMessages = [...rawMessages, ...socketMessages].map((msg, index) => {
    // Determine sender (me vs them) based on role or fallback
    const isMe = msg.sender?.role === 'buyer' || msg.sender === 'me';
    
    return {
      id: msg._id || msg.id || index,
      text: msg.text,
      sender: isMe ? "me" : "them",
      time: new Date(msg.createdAt || Date.now()).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isFile: msg.isFile || false,
      fileName: msg.fileName || ""
    };
  });

  const handleSendMessage = async () => {
    if (!inputText.trim()) return;

    try {
      const payload = {
        text: inputText,
        isFile: false,
        fileName: "",
        fileUrl: "",
        ...(isNewChat ? { recipientId: activeChat.recipientId } : {})
      };

      const res = await sendMessageApi({ conversationId: isNewChat ? "new" : activeChat.id, data: payload }).unwrap();
      const savedMsg = res.data;

      // Broadcast to socket
      socketRef.current.emit('send_message', { roomId: savedMsg.conversation || activeChat.id, message: savedMsg });

      // Add to local state instantly
      setSocketMessages(prev => [...prev, savedMsg]);
      setInputText("");
    } catch (err) {
      console.error("Failed to send message", err);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      handleSendMessage();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // File logic omitted for brevity, would similarly upload and call handleSendMessage with isFile=true
  };

  return (
    <div className="flex-1 bg-white border border-gray-200 rounded-md shadow-sm flex flex-col h-full overflow-hidden">
      {/* Chat Header */}
      <div className="flex items-center justify-between p-5 border-b border-gray-200 bg-white">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-[#E0E7FF] flex items-center justify-center font-bold text-[#3730A3] text-[15px]">
            {activeChat.sender.charAt(0)}
          </div>
          <div>
            <div className="flex items-center gap-1.5">
              <h2 className="text-[16px] font-bold text-[#0B172E] leading-tight">{activeChat.sender}</h2>
              {activeChat.isVerified && <CheckCircle size={14} className="text-[#DFB63E] fill-[#DFB63E]/20" />}
            </div>
            <div className="flex items-center gap-2 mt-0.5">
              <span className="flex items-center gap-1 text-[11px] text-green-600 font-bold">
                <div className="w-1.5 h-1.5 bg-green-500 rounded-full"></div>
                Online
              </span>
              <span className="text-[11px] text-gray-400 font-medium">• {activeChat.timeEstimate}</span>
            </div>
          </div>
        </div>
        <button className="text-[12px] font-bold text-gray-600 hover:text-[#0B172E] bg-gray-50 hover:bg-gray-100 transition-colors border border-gray-200 rounded-md px-3 py-1.5 cursor-pointer">
          View Profile
        </button>
      </div>

      {/* Chat History Area */}
      <div className="flex-1 p-6 overflow-y-auto bg-[#F9FAFB] flex flex-col gap-6">
        <div className="flex justify-center">
          <span className="text-[10px] font-bold text-gray-400 bg-gray-100 px-3 py-1 rounded-full uppercase tracking-wider">
            Conversation Started
          </span>
        </div>

        {allMessages.map((msg: any) => (
          <div key={msg.id} className={`flex flex-col max-w-[80%] ${msg.sender === "me" ? "self-end items-end" : "self-start items-start"}`}>
            <div className="flex items-end gap-2">
              {msg.sender === "them" && (
                <div className="w-6 h-6 rounded-full bg-[#E0E7FF] flex items-center justify-center font-bold text-[#3730A3] text-[10px] mb-1 flex-shrink-0">
                  {activeChat.sender.charAt(0)}
                </div>
              )}

              <div className={`p-3.5 rounded-2xl text-[13px] shadow-sm leading-relaxed ${msg.sender === "me"
                  ? "bg-[#0B172E] text-white rounded-br-[4px]"
                  : "bg-white border border-gray-200 text-gray-800 rounded-bl-[4px]"
                }`}>
                {msg.isFile ? (
                  <div className="flex items-center gap-2 px-1">
                    <Paperclip size={16} className={msg.sender === "me" ? "text-gray-300" : "text-gray-500"} />
                    <span className="font-bold underline cursor-pointer">{msg.fileName}</span>
                  </div>
                ) : (
                  msg.text
                )}
              </div>
            </div>
            <span className={`text-[10px] text-gray-400 mt-1.5 font-medium ${msg.sender === "me" ? "mr-1" : "ml-9"}`}>
              {msg.time}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Chat Input Area */}
      <div className="p-4 border-t border-gray-200 bg-white">
        <div className="flex items-center gap-3">
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileChange}
            className="hidden"
          />
          <button
            onClick={() => fileInputRef.current?.click()}
            className="p-2 text-gray-400 hover:text-[#0B172E] transition-colors rounded-full hover:bg-gray-100 cursor-pointer flex-shrink-0"
          >
            <Paperclip size={20} />
          </button>
          <input
            type="text"
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type your message..."
            className="flex-1 bg-gray-50 border border-gray-200 rounded-full px-5 py-2.5 text-[14px] text-black focus:outline-none focus:ring-1 focus:ring-[#DFB63E] focus:bg-white transition-all"
          />
          <button
            onClick={handleSendMessage}
            className="bg-[#DFB63E] hover:bg-[#cba433] text-black p-2.5 rounded-full transition-colors flex items-center justify-center w-10 h-10 shadow-sm cursor-pointer flex-shrink-0"
          >
            <Send size={16} strokeWidth={2.5} className="mr-0.5 mt-0.5" />
          </button>
        </div>
      </div>
    </div>
  );
}

import { Search, Filter, CheckCircle, Clock } from "lucide-react";

export default function MessageSidebar({
  messages,
  activeTab,
  setActiveTab,
  activeMessage,
  setActiveMessage
}: any) {
  return (
    <div className="w-full md:w-[380px] bg-white border border-gray-200 rounded-md shadow-sm flex flex-col overflow-hidden h-full">
      {/* Tabs */}
      <div className="flex items-center border-b border-gray-200">
        <button
          onClick={() => setActiveTab("inbox")}
